function resize(){camera.aspect=innerWidth/innerHeight;camera.position.z=innerWidth<600?16.8:13.8;camera.position.y=innerWidth<600?5.0:4.4;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))}addEventListener('resize',resize);
const particles=[];
function burst(position,color,count=14,power=2.3){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(.035+Math.random()*.045,0),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));mesh.position.copy(position);scene.add(mesh);particles.push({mesh,velocity:new THREE.Vector3((Math.random()-.5)*power,Math.random()*power*.8,(Math.random()-.5)*power*.35),life:.45+Math.random()*.3,max:.75})}}
function spark(character,color){const p=character.root.position.clone();p.y=1.6;p.x+=character.isEnemy?-.55:.55;burst(p,color,12,2.1)}
function playTone(freq,duration=.08,type='sine',volume=.035){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch{}}
function updateBars(){document.querySelector('#playerHealth').style.width=`${Math.max(0,playerHP)}%`;document.querySelector('#enemyHealth').style.width=`${Math.max(0,enemyHP)}%`;document.querySelector('#playerHealthText').textContent=`${Math.max(0,Math.ceil(playerHP))}%`;document.querySelector('#enemyHealthText').textContent=`${Math.max(0,Math.ceil(enemyHP))}%`;document.querySelector('#clock').textContent=String(Math.ceil(remaining)).padStart(2,'0')}
let keys={},held={};const actionCooldown={punch:.55,kick:.86,special:2.7};
function performAttack(ch,type){if(!playing||ch.attack>0||ch.hit>0)return;if(type==='guard'){ch.guard=true;return}ch.guard=false;ch.attack=type==='special'?.62:type==='kick'?.42:.32;ch.attackType=type;playTone(type==='special'?175:type==='kick'?110:230,type==='special'?.28:.12,type==='kick'?'triangle':'sawtooth',type==='special'?.06:.025);if(ch===player){const target=enemy;if(Math.abs(ch.root.position.x-target.root.position.x)<2.05){const base=type==='special'?20:type==='kick'?13:8;const dealt=Math.max(2,base*(target.guard?.35:1)*(fighters[selected].type==='STRIKER'&&type==='punch'?1.25:1));enemyHP=Math.max(0,enemyHP-dealt);target.hit=.2;target.root.position.x+=ch.isEnemy?-.12:.12;spark(target,type==='special'?0xbe80ff:type==='kick'?0xffd073:0x68fff4);updateBars();if(enemyHP<=0)finishRound(true)}}else{if(Math.abs(ch.root.position.x-player.root.position.x)<2.0){let dmg=(type==='kick'?11:8)*(player.guard?.26:1);playerHP=Math.max(0,playerHP-dmg);player.hit=.2;player.root.position.x+=.12;spark(player,0xff557d);playTone(85,.14,'square',.025);updateBars();if(playerHP<=0)finishRound(false)}}}
function showToast(title,sub){toast.innerHTML=`<em>${sub}</em>${title}`;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1150)}
function startGame(){playerHP=enemyHP=100;remaining=60;round=1;roundWins=0;playing=true;elapsed=0;enemy.root.position.x=2.45;player.root.position.x=-2.45;document.querySelector('#playerName').innerHTML=`${fighters[selected].name}<small>${fighters[selected].role}</small>`;document.querySelector('#enemyName').innerHTML=`${fighters[1].name}<small>${fighters[1].role}</small>`;menu.style.display='none';hud.classList.add('active');controls.classList.add('active');document.querySelector('#result').classList.remove('show');updateBars();showToast('FIGHT!','ROUND 01');lastTime=performance.now()}
document.querySelector('#startFight').onclick=startGame;document.querySelector('#rematch').onclick=startGame;
function finishRound(won){if(!playing)return;playing=false;if(won)roundWins++;const result=document.querySelector('#result');document.querySelector('#resultEyebrow').textContent=won?'ARENA CHAMPION':'MATCH COMPLETE';document.querySelector('#resultTitle').textContent=won?'VICTORY':'DEFEAT';document.querySelector('#resultTitle').style.color=won?'var(--cyan)':'var(--pink)';document.querySelector('#resultText').textContent=won?'THE RIFT IS YOURS':'THE ARENA REMEMBERS';result.classList.add('show');controls.classList.remove('active');playTone(won?523:120,.5,'sine',.055)}
function doAction(action){if(action==='left'||action==='right'){keys[action]=true;return}if(action==='guard'){held.guard=true;player.guard=true;return}performAttack(player,action)}
function releaseAction(action){if(action==='left'||action==='right')keys[action]=false;if(action==='guard'){held.guard=false;player.guard=false}}
const keyMap={a:'left',arrowleft:'left',d:'right',arrowright:'right',j:'punch',k:'kick',l:'special',' ':'guard'};addEventListener('keydown',e=>{const action=keyMap[e.key.toLowerCase()];if(action){e.preventDefault();if(!keys[e.key]){keys[e.key]=true;if(action!=='left'&&action!=='right'&&action!=='guard')doAction(action);if(action==='guard')doAction(action)}}if(e.key==='Escape'&&playing)finishRound(false)});addEventListener('keyup',e=>{const action=keyMap[e.key.toLowerCase()];if(action){keys[e.key]=false;if(action==='left'||action==='right'||action==='guard')releaseAction(action)}});
document.querySelectorAll('.ctrl').forEach(button=>{const action=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);button.classList.add('held');doAction(action)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,e=>{button.classList.remove('held');releaseAction(action)})});
document.querySelector('#soundToggle').onclick=()=>{soundOn=!soundOn;document.querySelector('#soundToggle').innerHTML=`♫ &nbsp; SOUND ${soundOn?'ON':'OFF'}`;if(soundOn)playTone(500,.08)};
function updateCharacter(ch,dt){if(ch.attack>0)ch.attack=Math.max(0,ch.attack-dt);if(ch.hit>0)ch.hit=Math.max(0,ch.hit-dt);ch.walk+=dt*(Math.abs(ch.root.position.x-ch.baseX)>.01?12:3);const walk=Math.sin(ch.walk)*.055;ch.legs[0].rotation.x=walk;ch.legs[1].rotation.x=-walk;ch.arms[0].rotation.x=-walk*.8;ch.arms[1].rotation.x=walk*.8;ch.torso.rotation.z=Math.sin(ch.walk*.5)*.018;
if(ch.attack>0){const power=ch.attackType==='special'?1.15:ch.attackType==='kick'?.9:.85;ch.arms[0].rotation.x=-power;ch.arms[0].rotation.z=-.65;if(ch.attackType==='kick')ch.legs[0].rotation.x=-1.05;if(ch.attackType==='special'){ch.arms[1].rotation.x=-.8;ch.torso.rotation.z=.12}}else{ch.arms[0].rotation.x=walk*.8;ch.arms[0].rotation.z=0;ch.arms[1].rotation.x=-walk*.8;ch.arms[1].rotation.z=0}if(ch.guard){ch.arms[0].rotation.x=-.85;ch.arms[1].rotation.x=-.85;ch.arms[0].rotation.z=-.35;ch.arms[1].rotation.z=.35}if(ch.hit>0)ch.body.position.x=Math.sin(ch.hit*65)*.06;else ch.body.position.x=0;ch.root.position.y=Math.sin(elapsed*3+(ch.isEnemy?1:0))*.018}
function update(dt){elapsed+=dt;updateCharacter(player,dt);updateCharacter(enemy,dt);for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.velocity,dt);p.velocity.y-=5*dt;p.mesh.material.opacity=Math.max(0,p.life/p.max);p.mesh.scale.multiplyScalar(1-dt*.3);if(p.life<=0){scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();particles.splice(i,1)}}
if(playing){remaining=Math.max(0,remaining-dt);if(remaining===0){finishRound(playerHP>=enemyHP);return}let move=0;if(keys.a||keys.arrowleft||keys.left)move-=1;if(keys.d||keys.arrowright||keys.right)move+=1;if(move){player.root.position.x=THREE.MathUtils.clamp(player.root.position.x+move*3.1*dt,-4.1,1.2);player.baseX=player.root.position.x;player.walk+=dt*5}player.guard=!!held.guard||!!keys[' '];aiTimer-=dt;const dist=enemy.root.position.x-player.root.position.x;if(aiTimer<=0){if(dist>1.8&&Math.random()<.54){enemy.root.position.x-=Math.min(dist-1.6,1.05);enemy.walk+=dt*5}else if(dist<2.1){if(Math.random()<.24){enemy.guard=true;setTimeout(()=>enemy.guard=false,400)}else performAttack(enemy,Math.random()<.37?'kick':'punch')}aiTimer=.5+Math.random()*.9}if(dist<1.6&&enemy.attack<=0&&Math.random()<dt*.8)performAttack(enemy,'punch');if(Math.abs(dist)>1.9)enemy.root.position.x=Math.max(player.root.position.x+1.55,enemy.root.position.x);enemy.root.position.x=Math.min(4.1,enemy.root.position.x)}
// cinematic idle sway, camera micro drift
player.root.position.z=Math.sin(elapsed*1.3)*.035;enemy.root.position.z=Math.cos(elapsed*1.1)*.035;cyanLight.intensity=42+Math.sin(elapsed*2)*8;pinkLight.intensity=42+Math.cos(elapsed*1.7)*7;ring.rotation.z=elapsed*.03;ring2.rotation.z=-elapsed*.02}
function render(now){const dt=Math.min(.04,(now-lastTime)/1000||.016);lastTime=now;update(dt);renderer.render(scene,camera);requestAnimationFrame(render)}requestAnimationFrame(render);
</script></body></html>

